1	package vault
2	
3	import (
4		"crypto/sha256"
5		"encoding/base64"
6		"encoding/hex"
7		"errors"
8		"fmt"
9		"os"
10		"path/filepath"
11		"reflect"
12		"sort"
13	)
14	
15	// ExportResult summarizes a successful snapshot export.
16	type ExportResult struct {
17		Name    string
18		Entries int
19		Objects int
20	}
21	
22	// ImportResult summarizes a successful snapshot import.
23	type ImportResult struct {
24		Name       string
25		Entries    int
26		NewObjects int
27	}
28	
29	// ExportSnapshot writes the named snapshot, together with the content objects
30	// it needs, to output as a portable package.
31	//
32	// Without a base the package is complete: every referenced object is carried,
33	// and a digest shared by several entries is carried once. With base set to the
34	// name of another snapshot in the same repository, the package still records
35	// the target's complete mapping but only carries objects the base does not
36	// reference; an importer can only apply it on top of an identical base.
37	//
38	// Every object the target references is re-read and checked for recorded size
39	// and SHA-256, including objects omitted from a delta, so a corrupt snapshot
40	// record or a missing/damaged object never produces a successful package.
41	//
42	// The output location is held to the same rules as a download: it must be
43	// outside the source repository (judged on actual locations, through
44	// symlinks, and before the file exists), its parent directory must already
45	// exist, an existing output must be a regular file that is not hard-linked to
46	// any index, snapshot record, lock file, or content object, and the package
47	// is committed through a descriptor pinned to the resolved parent directory,
48	// so a parent swapped for a symlink into the repository while the export runs
49	// is detected at commit time and can never redirect the package onto a
50	// repository file. The package is assembled in memory and written to a
51	// temporary file in that directory before an atomic rename: a failed export
52	// never creates or alters the output file.
53	func (s *Store) ExportSnapshot(name, base, output string) (ExportResult, error) {
54		if err := validateName(name); err != nil {
55			return ExportResult{}, err
56		}
57		if base != "" {
58			if err := validateName(base); err != nil {
59				return ExportResult{}, err
60			}
61		}
62		if output == "" {
63			return ExportResult{}, errors.New("output is required")
64		}
65		// Export reads an existing, initialized repository; it never creates one.
66		// The root and index are checked before taking the lock (withLockOpts
67		// passes createRoot=false so even the root directory is not materialized),
68		// and re-checked while holding the lock.
69		rootInfo, err := os.Stat(s.root)
70		switch {
71		case errors.Is(err, os.ErrNotExist):
72			return ExportResult{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
73		case err != nil:
74			return ExportResult{}, err
75		case !rootInfo.IsDir():
76			return ExportResult{}, fmt.Errorf("repository root %q is not a directory", s.root)
77		}
78		if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
79			return ExportResult{}, fmt.Errorf("repository %q is not initialized; run init first", s.root)
80		} else if err != nil {
81			return ExportResult{}, err
82		}
83		var result ExportResult
84		err = s.withLockOpts(true, false, func() error {
85			if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
86				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
87			} else if err != nil {
88				return err
89			}
90			// Validate the destination before reading any object or staging a
91			// temporary file, and hold the pinned parent directory until commit.
92			absOut, mode, pin, err := s.checkOutputSafe(output)
93			if err != nil {
94				return err
95			}
96			defer pin.Close()
97	
98			target, err := s.loadSnapshotRecord(name)
99			if err != nil {
100				return err
101			}
102			pkg := &Package{
103				Format:   packageFormat,
104				Version:  packageVersion,
105				Snapshot: target,
106				Objects:  []PackageObject{},
107			}
108			var baseSnap Snapshot
109			if base != "" {
110				var err error
111				baseSnap, err = s.loadSnapshotRecord(base)
112				if err != nil {
113					return fmt.Errorf("cannot use base snapshot: %w", err)
114				}
115				pkg.Base = &baseSnap
116			}
117	
118			// Verify every object the target references, reading each once. This
119			// includes objects the delta omits because the base references them:
120			// certifying the delta requires those to be intact too. Only objects
121			// the base does not reference are carried. Digests are processed in
122			// sorted order so the package layout and any failure message are
123			// deterministic.
124			carry := digestsReferenced(target.Entries)
125			if base != "" {
126				for digest := range digestsReferenced(baseSnap.Entries) {
127					delete(carry, digest)
128				}
129			}
130			for _, digest := range sortedDigests(target.Entries) {
131				content, size, err := s.readVerifiedObject(digest, target.Entries)
132				if err != nil {
133					return fmt.Errorf("snapshot %q references unusable object %s: %w", name, digest, err)
134				}
135				if _, included := carry[digest]; !included {
136					continue
137				}
138				pkg.Objects = append(pkg.Objects, PackageObject{
139					Digest: digest,
140					Size:   size,
141					Data:   base64.StdEncoding.EncodeToString(content),
142				})
143			}
144	
145			data, err := marshalPackage(pkg)
146			if err != nil {
147				return err
148			}
149			if err := s.writeOutputPackage(pin, absOut, data, mode); err != nil {
150				return err
151			}
152			result = ExportResult{Name: name, Entries: len(target.Entries), Objects: len(pkg.Objects)}
153			return nil
154		})
155		if err != nil {
156			return ExportResult{}, err
157		}
158		return result, nil
159	}
160	
161	// writeOutputPackage stages the package as a complete temporary file inside
162	// the pinned parent directory and commits it via Store.commitOutput, which
163	// revalidates the destination immediately before the atomic rename. On any
164	// failure the temporary file is removed and an existing output is never
165	// touched.
166	func (s *Store) writeOutputPackage(pin *parentPin, absOut string, data []byte, mode os.FileMode) error {
167		tmp, tmpBase, err := createTempIn(pin, ".package-")
168		if err != nil {
169			return fmt.Errorf("cannot create temporary file for output: %w", err)
170		}
171		committed := false
172		defer func() {
173			if !committed {
174				removeTempIn(pin, tmpBase)
175			}
176		}()
177		if err := tmp.Chmod(mode); err != nil {
178			tmp.Close()
179			return fmt.Errorf("cannot prepare output file: %w", err)
180		}
181		if _, err := tmp.Write(data); err != nil {
182			tmp.Close()
183			return fmt.Errorf("cannot write output %q: %w", absOut, err)
184		}
185		if err := tmp.Sync(); err != nil {
186			tmp.Close()
187			return fmt.Errorf("cannot write output %q: %w", absOut, err)
188		}
189		if err := tmp.Close(); err != nil {
190			return fmt.Errorf("cannot write output %q: %w", absOut, err)
191		}
192		if err := s.commitOutput(pin, tmpBase, absOut); err != nil {
193			return err
194		}
195		committed = true
196		_ = syncDirectory(pin.f)
197		return nil
198	}
199	
200	// ImportSnapshot imports a snapshot package produced by ExportSnapshot into an
201	// initialized repository.
202	//
203	// Import only adds the package's snapshot and any missing content objects; it
204	// never changes the current name mapping or any existing snapshot or object.
205	// A delta package is accepted only when the destination already contains a
206	// snapshot with the base name and byte-identical entry metadata, and every
207	// object the delta omits is present and intact. Healthy objects already in the
208	// destination are reused; re-importing a package whose snapshot is already
209	// present with identical metadata succeeds without creating a second copy. A
210	// same-named snapshot with different metadata is refused.
211	//
212	// Every target record's size must equal the actual byte count of the content
213	// its digest names, checked separately for each name that references it.
214	// Carried content is measured while the package is decoded; content a delta
215	// omits is measured from the destination (after the matching base has proven
216	// it present and healthy) before anything is written. A record that keeps a
217	// valid digest but declares another size therefore rejects the entire
218	// package — other correct records and other correct new objects included —
219	// and names the target snapshot, artifact, digest, recorded size, and actual
220	// byte count as record corruption rather than a checksum failure.
221	//
222	// All validation and reuse happens before anything is written, so a rejected
223	// package adds no object, snapshot, or temporary file. New objects then land
224	// as complete files via temp-file-and-rename, and the snapshot record is
225	// renamed into place only after every object the mapping references has been
226	// verified. Consequently only an actual crash or write failure between those
227	// two commits can leave an unreferenced complete object, which a later gc
228	// removes and a retry completes; a partially imported snapshot can never be
229	// observed.
230	func (s *Store) ImportSnapshot(file string) (ImportResult, error) {
231		if file == "" {
232			return ImportResult{}, errors.New("file is required")
233		}
234		data, err := os.ReadFile(file)
235		if err != nil {
236			return ImportResult{}, err
237		}
238		pkg, err := decodePackage(data)
239		if err != nil {
240			return ImportResult{}, err
241		}
242		// Import targets an initialized repository; it never creates one the way
243		// mutating artifact commands do.
244		rootInfo, err := os.Stat(s.root)
245		switch {
246		case errors.Is(err, os.ErrNotExist):
247			return ImportResult{}, fmt.Errorf("repository %q does not exist; run init first", s.root)
248		case err != nil:
249			return ImportResult{}, err
250		case !rootInfo.IsDir():
251			return ImportResult{}, fmt.Errorf("repository root %q is not a directory", s.root)
252		}
253		var result ImportResult
254		err = s.withLock(true, func() error {
255			if _, err := os.Stat(s.indexPath()); errors.Is(err, os.ErrNotExist) {
256				return fmt.Errorf("repository %q is not initialized; run init first", s.root)
257			} else if err != nil {
258				return err
259			}
260			if err := rejectLinkedDirs(s.root); err != nil {
261				return err
262			}
263	
264			// A delta must sit on an exactly matching base: same snapshot name and
265			// identical entry metadata. A merely same-named snapshot, or objects
266			// that happen to share digests, is not a base.
267			if pkg.Base != nil {
268				existing, err := s.loadSnapshotRecord(pkg.Base.Name)
269				if err != nil {
270					return fmt.Errorf("delta base snapshot %q is unavailable: %w", pkg.Base.Name, err)
271				}
272				if !snapshotsEqual(existing, *pkg.Base) {
273					return fmt.Errorf("delta base snapshot %q does not match the package base", pkg.Base.Name)
274				}
275				if err := s.verifyReferencedObjects(pkg.Base.Name, existing.Entries); err != nil {
276					return fmt.Errorf("delta base snapshot %q is not fully present: %w", pkg.Base.Name, err)
277				}
278			}
279	
280			// Record sizes are validated against carried payloads when the package
281			// is decoded. Objects a delta omits are not carried, so their sizes are
282			// measured from the destination here — while the matching base has just
283			// proven them present and healthy — before anything is staged. A target
284			// entry that keeps a valid digest but declares another byte count is a
285			// corrupt record: it rejects the whole import, including every other
286			// correct entry and any new object the package carries, so a failed
287			// import can never install even one unreferenced content object.
288			if err := s.verifyOmittedEntrySizes(pkg); err != nil {
289				return err
290			}
291	
292			// A same-named destination snapshot is either identical metadata or a
293			// collision. A collision is refused before anything is staged.
294			targetPath := s.snapshotPath(pkg.Snapshot.Name)
295			identicalSnapshot := false
296			if existing, statErr := os.Lstat(targetPath); statErr == nil {
297				if existing.Mode()&os.ModeSymlink != 0 {
298					return fmt.Errorf("snapshot path %q is a symbolic link", targetPath)
299				}
300				current, err := s.loadSnapshotRecord(pkg.Snapshot.Name)
301				if err != nil {
302					return fmt.Errorf("snapshot %q already exists and is unusable: %w", pkg.Snapshot.Name, err)
303				}
304				if !snapshotsEqual(current, pkg.Snapshot) {
305					return fmt.Errorf("snapshot %q already exists with different metadata; refusing to overwrite", pkg.Snapshot.Name)
306				}
307				identicalSnapshot = true
308				// Fast path: everything the published snapshot needs is already
309				// present and healthy, so the import is a no-op.
310				if s.verifyReferencedObjects(pkg.Snapshot.Name, pkg.Snapshot.Entries) == nil {
311					result = ImportResult{Name: pkg.Snapshot.Name, Entries: len(pkg.Snapshot.Entries), NewObjects: 0}
312					return nil
313				}
314				// Otherwise fall through: a carried object that is merely missing
315				// can be staged to complete an earlier interrupted import, while a
316				// damaged existing object still aborts below.
317			} else if !errors.Is(statErr, os.ErrNotExist) {
318				return statErr
319			}
320	
321			objects, err := pkg.materialize()
322			if err != nil {
323				return err
324			}
325	
326			// Phase 1, no writes: classify every carried object. Existing files
327			// must be healthy and are reused; a damaged one aborts the import and
328			// is reported by digest.
329			toAdd := make([]objectContent, 0, len(objects))
330			for _, obj := range objects {
331				path := s.objectPath(obj.digest)
332				info, err := os.Lstat(path)
333				switch {
334				case err == nil:
335					if info.Mode()&os.ModeSymlink != 0 {
336						return fmt.Errorf("object %s: object path is a symbolic link", obj.digest)
337					}
338					if !info.Mode().IsRegular() {
339						return fmt.Errorf("object %s: object path is not a regular file", obj.digest)
340					}
341					// Record sizes were validated against the carried payload when
342					// the package was decoded; only the existing object's own type
343					// and checksum still need to prove healthy before reuse.
344					if _, _, err := s.readHealthyObject(obj.digest); err != nil {
345						return fmt.Errorf("object %s already present but damaged: %w", obj.digest, err)
346					}
347				case errors.Is(err, os.ErrNotExist):
348					toAdd = append(toAdd, obj)
349				default:
350					return err
351				}
352			}
353	
354			// Phase 2: stage missing objects as complete, content-addressed files.
355			// A failure here leaves only unreferenced complete objects behind; a
356			// retry reuses them and finishes the import.
357			for _, obj := range toAdd {
358				if err := s.stageObject(obj.digest, obj.content); err != nil {
359					return err
360				}
361			}
362	
363			// Phase 3: the published mapping must be fully restorable. This covers
364			// reused objects, newly staged ones, and everything omitted by a delta.
365			if err := s.verifyReferencedObjects(pkg.Snapshot.Name, pkg.Snapshot.Entries); err != nil {
366				return err
367			}
368	
369			// Phase 4: publish the snapshot record last (unless an identical one is
370			// already published). This rename is the commit point; before it a new
371			// imported snapshot simply does not exist.
372			if !identicalSnapshot {
373				if err := s.saveSnapshot(targetPath, pkg.Snapshot); err != nil {
374					return err
375				}
376			}
377			result = ImportResult{Name: pkg.Snapshot.Name, Entries: len(pkg.Snapshot.Entries), NewObjects: len(toAdd)}
378			return nil
379		})
380		if err != nil {
381			return ImportResult{}, err
382		}
383		return result, nil
384	}
385	
386	// loadSnapshotRecord reads and fully validates one stored snapshot: the path
387	// must be a regular file (never a symlink), the document must be a single
388	// well-formed object, carry a present non-null entries mapping, record the
389	// same name it is filed under (in full), and contain only valid entry records.
390	func (s *Store) loadSnapshotRecord(name string) (Snapshot, error) {
391		path := s.snapshotPath(name)
392		info, err := os.Lstat(path)
393		if errors.Is(err, os.ErrNotExist) {
394			return Snapshot{}, fmt.Errorf("snapshot %q not found", name)
395		}
396		if err != nil {
397			return Snapshot{}, err
398		}
399		if info.Mode()&os.ModeSymlink != 0 {
400			return Snapshot{}, fmt.Errorf("snapshot %q is a symbolic link", name)
401		}
402		if !info.Mode().IsRegular() {
403			return Snapshot{}, fmt.Errorf("snapshot %q is not a regular file", name)
404		}
405		data, err := os.ReadFile(path)
406		if err != nil {
407			return Snapshot{}, err
408		}
409		snap, err := decodeSnapshotRecord(data, name)
410		if err != nil {
411			return Snapshot{}, fmt.Errorf("snapshot %q is corrupted: %w", name, err)
412		}
413		return snap, nil
414	}
415	
416	// verifyReferencedObjects checks each distinct referenced digest once against
417	// the stored object's size and SHA-256.
418	func (s *Store) verifyReferencedObjects(snapshotName string, entries map[string]Entry) error {
419		for _, digest := range sortedDigests(entries) {
420			if _, _, err := s.readVerifiedObject(digest, entries); err != nil {
421				return fmt.Errorf("object %s needed by snapshot %q: %w", digest, snapshotName, err)
422			}
423		}
424		return nil
425	}
426	
427	// verifyOmittedEntrySizes enforces the target record-size rule for content the
428	// package does not carry (the objects a delta omits, which the destination
429	// must already hold). Sizes for carried content were checked against the
430	// payloads while the package was decoded, so this looks only at digests absent
431	// from the carried set: each target entry naming one must record the exact
432	// byte count of the healthy object already in the destination. Every name is
433	// checked separately, in sorted order, since one digest may back several
434	// entries. The check reads and hashes content but writes nothing; it runs
435	// before any object is staged, so a mismatch rejects the whole package
436	// without leaving even a correct new object behind.
437	func (s *Store) verifyOmittedEntrySizes(pkg *Package) error {
438		carried := make(map[string]struct{}, len(pkg.Objects))
439		for _, obj := range pkg.Objects {
440			carried[obj.Digest] = struct{}{}
441		}
442		actualByDigest := map[string]int64{}
443		for _, name := range sortedEntryNames(pkg.Snapshot.Entries) {
444			entry := pkg.Snapshot.Entries[name]
445			if _, isCarried := carried[entry.Digest]; isCarried {
446				continue
447			}
448			actual, ok := actualByDigest[entry.Digest]
449			if !ok {
450				_, size, err := s.readHealthyObject(entry.Digest)
451				if err != nil {
452					// A missing or damaged destination object is content trouble,
453					// reported through the same path as the later full verification.
454					return fmt.Errorf("object %s needed by snapshot %q: %w", entry.Digest, pkg.Snapshot.Name, err)
455				}
456				actual = size
457				actualByDigest[entry.Digest] = size
458			}
459			if entry.Size != actual {
460				return newEntrySizeMismatchError(pkg.Snapshot.Name, entry.Name, entry.Digest, entry.Size, actual)
461			}
462		}
463		return nil
464	}
465	
466	// readHealthyObject loads the content object filed under digest, requiring it
467	// to be a regular file (never a symlink or other special file) whose full
468	// bytes hash to digest. It returns the bytes and their true byte count but
469	// makes no claim about any recorded size, so callers can distinguish a
470	// checksum failure from a record whose size disagrees with healthy content.
471	func (s *Store) readHealthyObject(digest string) ([]byte, int64, error) {
472		path := s.objectPath(digest)
473		info, err := os.Lstat(path)
474		if err != nil {
475			return nil, 0, err
476		}
477		if info.Mode()&os.ModeSymlink != 0 {
478			return nil, 0, errors.New("object path is a symbolic link")
479		}
480		if !info.Mode().IsRegular() {
481			return nil, 0, errors.New("object path is not a regular file")
482		}
483		content, err := os.ReadFile(path)
484		if err != nil {
485			return nil, 0, err
486		}
487		sum := sha256.Sum256(content)
488		if actual := hex.EncodeToString(sum[:]); actual != digest {
489			return nil, 0, fmt.Errorf("content checksum is %s", actual)
490		}
491		return content, int64(len(content)), nil
492	}
493	
494	// readVerifiedObject reads a content object and returns its bytes, confirming
495	// its SHA-256 digest and the size recorded for it in the given entries.
496	func (s *Store) readVerifiedObject(digest string, entries map[string]Entry) ([]byte, int64, error) {
497		content, size, err := s.readHealthyObject(digest)
498		if err != nil {
499			return nil, 0, err
500		}
501		// Every entry referencing this digest must agree on the size; a content
502		// hash fixes the byte count, so a disagreement is a corrupt record.
503		for _, entry := range entries {
504			if entry.Digest == digest && size != entry.Size {
505				return nil, 0, fmt.Errorf("content is %d bytes, record for %q says %d", size, entry.Name, entry.Size)
506			}
507		}
508		return content, size, nil
509	}
510	
511	// stageObject writes one missing object to a temp file and renames it into
512	// place. The content digest was verified when the package was decoded, so the
513	// final file is complete before it ever appears under its digest name.
514	func (s *Store) stageObject(digest string, content []byte) error {
515		tmp, err := os.CreateTemp(filepath.Join(s.root, "objects"), ".import-*")
516		if err != nil {
517			return err
518		}
519		tmpName := tmp.Name()
520		defer os.Remove(tmpName)
521		if _, err := tmp.Write(content); err != nil {
522			tmp.Close()
523			return fmt.Errorf("object %s: %w", digest, err)
524		}
525		if err := tmp.Close(); err != nil {
526			return fmt.Errorf("object %s: %w", digest, err)
527		}
528		if err := os.Rename(tmpName, s.objectPath(digest)); err != nil {
529			return fmt.Errorf("object %s: %w", digest, err)
530		}
531		return nil
532	}
533	
534	// rejectLinkedDirs makes sure an import can never stage files outside the
535	// repository through a replaced objects or snapshots directory.
536	func rejectLinkedDirs(root string) error {
537		for _, dir := range []string{filepath.Join(root, "objects"), filepath.Join(root, "snapshots")} {
538			if err := ensureRealDir(dir); err != nil {
539				return err
540			}
541		}
542		return nil
543	}
544	
545	// snapshotsEqual reports whether two snapshot records carry the same snapshot
546	// name and identical metadata for every entry.
547	func snapshotsEqual(a, b Snapshot) bool {
548		return reflect.DeepEqual(a.Entries, b.Entries) && a.Name == b.Name
549	}
550	
551	func sortedDigests(entries map[string]Entry) []string {
552		seen := map[string]struct{}{}
553		for _, entry := range entries {
554			seen[entry.Digest] = struct{}{}
555		}
556		out := make([]string, 0, len(seen))
557		for digest := range seen {
558			out = append(out, digest)
559		}
560		sort.Strings(out)
561		return out
562	}
563

