1	package vault
2	
3	import (
4		"bytes"
5		"crypto/sha256"
6		"encoding/base64"
7		"encoding/hex"
8		"encoding/json"
9		"errors"
10		"fmt"
11		"io"
12		"sort"
13	)
14	
15	// Package format:
16	//
17	// A snapshot package is an indented JSON document that moves one complete
18	// snapshot, together with whatever content objects it needs, between
19	// repositories. A full package carries every referenced object; an
20	// incremental package records a Base and only carries objects the base
21	// snapshot does not reference. Either way Snapshot always holds the complete
22	// target mapping — additions, overwrites, and deletions relative to the base
23	// are expressed solely by that mapping.
24	//
25	//	{
26	//	  "format": "artifact-vault-snapshot",
27	//	  "version": 1,
28	//	  "snapshot": { "name": "...", "entries": { ... } },
29	//	  "base": { "name": "...", "entries": { ... } },     // delta only, optional
30	//	  "objects": [
31	//	    { "digest": "<sha256 hex>", "size": 123, "data": "<base64>" }
32	//	  ]
33	//	}
34	//
35	// An object's SHA-256 digest over its decoded bytes is also its filename
36	// inside objects/, so no package record can name a destination outside that
37	// directory.
38	const (
39		packageFormat  = "artifact-vault-snapshot"
40		packageVersion = 1
41	)
42	
43	// PackageObject is one content object carried by a package.
44	type PackageObject struct {
45		Digest string `json:"digest"`
46		Size   int64  `json:"size"`
47		Data   string `json:"data"`
48	}
49	
50	// Package is the on-disk snapshot transfer format.
51	type Package struct {
52		Format   string          `json:"format"`
53		Version  int             `json:"version"`
54		Snapshot Snapshot        `json:"snapshot"`
55		Base     *Snapshot       `json:"base,omitempty"`
56		Objects  []PackageObject `json:"objects"`
57	}
58	
59	// rejectDuplicateKeys walks the raw JSON token stream and fails if any object
60	// lists the same key twice. encoding/json otherwise keeps only the last
61	// occurrence, which could hide a duplicate object or entry behind an earlier,
62	// validated one.
63	func rejectDuplicateKeys(data []byte) error {
64		type frame struct {
65			object    bool
66			keys      map[string]struct{}
67			expectKey bool
68		}
69		dec := json.NewDecoder(bytes.NewReader(data))
70		var stack []frame
71		for {
72			tok, err := dec.Token()
73			if err == io.EOF {
74				return nil
75			}
76			if err != nil {
77				return err
78			}
79			switch t := tok.(type) {
80			case json.Delim:
81				switch t {
82				case '{':
83					stack = append(stack, frame{object: true, keys: map[string]struct{}{}, expectKey: true})
84				case '[':
85					stack = append(stack, frame{object: false})
86				case '}', ']':
87					if len(stack) == 0 {
88						return errors.New("unbalanced JSON delimiters")
89					}
90					stack = stack[:len(stack)-1]
91					// The composite value just consumed completes an entry in the
92					// enclosing object, so its next string is another key.
93					if len(stack) > 0 && stack[len(stack)-1].object {
94						stack[len(stack)-1].expectKey = true
95					}
96				}
97			case string:
98				if len(stack) > 0 && stack[len(stack)-1].object {
99					f := &stack[len(stack)-1]
100					if f.expectKey {
101						if _, dup := f.keys[t]; dup {
102							return fmt.Errorf("duplicate key %q", t)
103						}
104						f.keys[t] = struct{}{}
105						f.expectKey = false
106					} else {
107						f.expectKey = true
108					}
109				}
110			default:
111				// Primitive value in an object frame: the next string token is a key.
112				if len(stack) > 0 && stack[len(stack)-1].object {
113					stack[len(stack)-1].expectKey = true
114				}
115			}
116		}
117	}
118	
119	// marshalPackage serializes the package as indented JSON.
120	func marshalPackage(pkg *Package) ([]byte, error) {
121		data, err := json.MarshalIndent(pkg, "", "  ")
122		if err != nil {
123			return nil, err
124		}
125		return append(data, '\n'), nil
126	}
127	
128	// decodePackage parses a package without touching any repository. It enforces
129	// every self-contained invariant the specification places on a package:
130	//
131	//   - known format and version;
132	//   - snapshot (and base, if present) records are complete and valid:
133	//     snapshot name legal, entries keyed by their recorded name, legal names,
134	//     64 lowercase-hex digests, non-negative sizes;
135	//   - every object digest is valid and unique, the base64 data decodes, and
136	//     its length and SHA-256 match the record;
137	//   - the object set carries exactly the objects required by the snapshot
138	//     mapping minus the base mapping (all of them for a full package),
139	//     neither omitting a referenced digest nor carrying an unreferenced one;
140	//   - every target entry records the exact byte count of the content its
141	//     digest identifies when that content is carried: an entry keeping a valid
142	//     digest but declaring another size is a corrupt record, even though the
143	//     object record itself is intact.
144	//
145	// Sizes for objects a delta omits cannot be checked until the package meets a
146	// matching, healthy base in the destination; import performs that check before
147	// anything is written. Other cross-repository checks (an existing base
148	// snapshot, objects already present in the destination, name collisions) are
149	// likewise performed later by import, which has the destination in hand.
150	func decodePackage(data []byte) (*Package, error) {
151		// encoding/json silently keeps the last value when an object lists a key
152		// twice; that would let a package hide a duplicate entry or overwrite a
153		// structural field. Reject any such document before decoding it.
154		if err := rejectDuplicateKeys(data); err != nil {
155			return nil, fmt.Errorf("invalid package: %w", err)
156		}
157		dec := json.NewDecoder(bytes.NewReader(data))
158		dec.DisallowUnknownFields()
159		var raw struct {
160			Format   string             `json:"format"`
161			Version  int                `json:"version"`
162			Snapshot Snapshot           `json:"snapshot"`
163			Base     *Snapshot          `json:"base,omitempty"`
164			Objects  *[]json.RawMessage `json:"objects"`
165		}
166		if err := dec.Decode(&raw); err != nil {
167			return nil, fmt.Errorf("invalid package: %w", err)
168		}
169		if tok, err := dec.Token(); err != io.EOF {
170			if err == nil {
171				return nil, fmt.Errorf("invalid package: unexpected trailing content after top-level value (%v)", tok)
172			}
173			return nil, fmt.Errorf("invalid package: %w", err)
174		}
175		if raw.Format != packageFormat {
176			return nil, fmt.Errorf("invalid package: unknown format %q", raw.Format)
177		}
178		if raw.Version != packageVersion {
179			return nil, fmt.Errorf("invalid package: unsupported version %d (supported: %d)", raw.Version, packageVersion)
180		}
181		if raw.Objects == nil {
182			return nil, errors.New("invalid package: missing objects array")
183		}
184	
185		pkg := &Package{Format: raw.Format, Version: raw.Version, Objects: []PackageObject{}}
186		if err := validateSnapshotRecord("snapshot", raw.Snapshot); err != nil {
187			return nil, err
188		}
189		pkg.Snapshot = raw.Snapshot
190		if raw.Base != nil {
191			if err := validateSnapshotRecord("base", *raw.Base); err != nil {
192				return nil, err
193			}
194			pkg.Base = raw.Base
195		}
196	
197		seen := map[string]struct{}{}
198		for i, item := range *raw.Objects {
199			var obj PackageObject
200			odec := json.NewDecoder(bytes.NewReader(item))
201			odec.DisallowUnknownFields()
202			if err := odec.Decode(&obj); err != nil {
203				return nil, fmt.Errorf("invalid package: object %d: %w", i, err)
204			}
205			if _, err := odec.Token(); err != io.EOF {
206				if err == nil {
207					return nil, fmt.Errorf("invalid package: object %d: trailing content", i)
208				}
209				return nil, fmt.Errorf("invalid package: object %d: %w", i, err)
210			}
211			if !isDigest(obj.Digest) {
212				return nil, fmt.Errorf("invalid package: object %d: digest %q is not 64 lowercase hex characters", i, obj.Digest)
213			}
214			if obj.Size < 0 {
215				return nil, fmt.Errorf("invalid package: object %s has negative size %d", obj.Digest, obj.Size)
216			}
217			if _, dup := seen[obj.Digest]; dup {
218				return nil, fmt.Errorf("invalid package: duplicate object %s", obj.Digest)
219			}
220			seen[obj.Digest] = struct{}{}
221			content, err := base64.StdEncoding.DecodeString(obj.Data)
222			if err != nil {
223				return nil, fmt.Errorf("invalid package: object %s: data is not valid base64: %w", obj.Digest, err)
224			}
225			if int64(len(content)) != obj.Size {
226				return nil, fmt.Errorf("invalid package: object %s: data is %d bytes, record says %d", obj.Digest, len(content), obj.Size)
227			}
228			sum := sha256.Sum256(content)
229			if actual := hex.EncodeToString(sum[:]); actual != obj.Digest {
230				return nil, fmt.Errorf("invalid package: object %s: content checksum is %s", obj.Digest, actual)
231			}
232			pkg.Objects = append(pkg.Objects, obj)
233		}
234	
235		needed := digestsReferenced(pkg.Snapshot.Entries)
236		if pkg.Base != nil {
237			for digest := range digestsReferenced(pkg.Base.Entries) {
238				delete(needed, digest)
239			}
240		}
241		carried := map[string]int64{}
242		for _, obj := range pkg.Objects {
243			carried[obj.Digest] = obj.Size
244		}
245		for digest := range needed {
246			if _, ok := carried[digest]; !ok {
247				return nil, fmt.Errorf("invalid package: required object %s is missing from the package", digest)
248			}
249		}
250		for digest := range carried {
251			if _, ok := needed[digest]; !ok {
252				return nil, fmt.Errorf("invalid package: object %s is not referenced by the target mapping", digest)
253			}
254		}
255		// Every target entry whose content the package carries must record the
256		// carried content's exact byte count. The object's own record was already
257		// proven to match its payload above, so an entry size that disagrees is a
258		// corrupt snapshot record rather than corrupt content. Each name is
259		// checked separately: one digest may be referenced by several entries, and
260		// all of them must agree. Objects a delta omits are checked later against
261		// the destination by import. Entries are visited in name order so the
262		// first reported artifact is deterministic.
263		for _, key := range sortedEntryNames(pkg.Snapshot.Entries) {
264			entry := pkg.Snapshot.Entries[key]
265			actual, isCarried := carried[entry.Digest]
266			if isCarried && entry.Size != actual {
267				return nil, fmt.Errorf("invalid package: %w", newEntrySizeMismatchError(pkg.Snapshot.Name, entry.Name, entry.Digest, entry.Size, actual))
268			}
269		}
270		return pkg, nil
271	}
272	
273	// sortedEntryNames returns a snapshot's entry keys in sorted order, so checks
274	// that may report one of several entries name a deterministic artifact.
275	func sortedEntryNames(entries map[string]Entry) []string {
276		names := make([]string, 0, len(entries))
277		for name := range entries {
278			names = append(names, name)
279		}
280		sort.Strings(names)
281		return names
282	}
283	
284	// entrySizeMismatchError reports a target snapshot entry whose recorded size
285	// disagrees with the actual byte count of the content its digest identifies.
286	// The digest matches healthy content, so this is record corruption — distinct
287	// from a checksum failure or missing content — and the fields name everything
288	// a user needs to tell them apart.
289	type entrySizeMismatchError struct {
290		snapshot string
291		artifact string
292		digest   string
293		recorded int64
294		actual   int64
295	}
296	
297	func newEntrySizeMismatchError(snapshot, artifact, digest string, recorded, actual int64) error {
298		return entrySizeMismatchError{snapshot: snapshot, artifact: artifact, digest: digest, recorded: recorded, actual: actual}
299	}
300	
301	func (e entrySizeMismatchError) Error() string {
302		return fmt.Sprintf("snapshot %q entry %q references content %s but records size %d; the content is %d bytes",
303			e.snapshot, e.artifact, e.digest, e.recorded, e.actual)
304	}
305	
306	// validateSnapshotRecord validates one embedded snapshot the same way restore
307	// and gc validate on-disk snapshots.
308	func validateSnapshotRecord(scope string, snap Snapshot) error {
309		if err := validateName(snap.Name); err != nil {
310			return fmt.Errorf("invalid package: %s snapshot name %q is not a legal snapshot name", scope, snap.Name)
311		}
312		if snap.Entries == nil {
313			return fmt.Errorf("invalid package: %s snapshot %q is missing its entries mapping", scope, snap.Name)
314		}
315		for key, entry := range snap.Entries {
316			if err := validateEntryRecord(key, entry); err != nil {
317				return fmt.Errorf("invalid package: %s snapshot %q: %w", scope, snap.Name, err)
318			}
319		}
320		return nil
321	}
322	
323	// digestsReferenced returns the set of object digests referenced by a set of
324	// snapshot entries. Multiple entries may share one digest.
325	func digestsReferenced(entries map[string]Entry) map[string]struct{} {
326		digests := make(map[string]struct{}, len(entries))
327		for _, entry := range entries {
328			digests[entry.Digest] = struct{}{}
329		}
330		return digests
331	}
332	
333	// objectContent is a decoded package object kept in memory during import.
334	type objectContent struct {
335		digest  string
336		size    int64
337		content []byte
338	}
339	
340	// materialize decodes the base64 payloads of every carried object into
341	// memory. Import holds the objects while it stages them; packages are
342	// bounded artifacts meant to be copied between machines.
343	func (p *Package) materialize() ([]objectContent, error) {
344		objects := make([]objectContent, 0, len(p.Objects))
345		// Sort so staging order (and any error message) is deterministic.
346		ordered := append([]PackageObject(nil), p.Objects...)
347		sort.Slice(ordered, func(i, j int) bool { return ordered[i].Digest < ordered[j].Digest })
348		for _, obj := range ordered {
349			content, err := base64.StdEncoding.DecodeString(obj.Data)
350			if err != nil {
351				return nil, fmt.Errorf("object %s: %w", obj.Digest, err)
352			}
353			objects = append(objects, objectContent{digest: obj.Digest, size: obj.Size, content: content})
354		}
355		return objects, nil
356	}
