18	// Get downloads the artifact recorded under name in the current index to the
19	// output path. Nothing is delivered unless the stored object is complete and
20	// the destination is safe:
21	//
22	//   - the index and the selected record must be usable (parseable, with a
23	//     name mapping, the recorded name matching its key, a 64-character
24	//     lowercase-hex digest, and a non-negative size);
25	//   - the object must exist, be a regular file, and its actual size and
26	//     SHA-256 must match the record;
27	//   - the output must be outside the repository (including through a
28	//     symlinked parent), its parent directory must exist, and an existing
29	//     output must be a regular file that is not a hard link to any repository
30	//     file.
31	//
32	// The object is streamed and hashed into a temporary file beside the output;
33	// only after the complete, verified bytes are flushed is the output renamed
34	// into place. A failed download therefore leaves an existing output
35	// byte-for-byte intact and a missing output absent; an interrupted process
36	// leaves at most an unreferenced temporary file that a later download
37	// replaces without manual cleanup.
38	func (s *Store) Get(name, output string) error {
39		if err := validateName(name); err != nil {
40			return err
41		}
42		if output == "" {
43			return errors.New("output is required")
44		}
45		return s.withLock(false, func() error {
46			return s.getLocked(name, output)
47		})
48	}
