180		src, srcStore := seedVault(t, map[string]string{
181			"keep.txt":   "same",
182			"change.txt": "old",
183			"gone.txt":   "leaving",
184		})
185		if _, err := New(src).CreateSnapshot("base"); err != nil {
186			t.Fatal(err)
187		}
188		// Evolve the mapping: overwrite change.txt, add new.txt, drop gone.txt.
189		if _, err := New(src).Put("change.txt", writeFile(t, "new")); err != nil {
190			t.Fatal(err)
191		}
192		if _, err := New(src).Put("new.txt", writeFile(t, "brand new")); err != nil {
193			t.Fatal(err)
194		}
195		idx, err := srcStore.loadStrictValidEntries()
196		if err != nil {
197			t.Fatal(err)
198		}
199		delete(idx.Entries, "gone.txt")
200		target := Snapshot{Name: "target", Entries: idx.Entries}
201		if err := srcStore.saveSnapshot(srcStore.snapshotPath("target"), target); err != nil {
202			t.Fatal(err)
203		}
204	
205		full := filepath.Join(t.TempDir(), "base.pkg")
206		delta := filepath.Join(t.TempDir(), "target.pkg")
207		if res := mustExport(t, src, "base", "", full); res.Objects != 3 {
208			t.Fatalf("base objects=%d, want 3", res.Objects)
209		}
210		res := mustExport(t, src, "target", "base", delta)
211		// Base digests: same, old, leaving. Target digests: same, new, brand new.
212		// The delta carries the two non-base digests despite three entries.
213		if res.Entries != 3 || res.Objects != 2 {
214			t.Fatalf("delta result=%+v, want 3 entries 2 objects", res)
215		}
216	
217		dst := filepath.Join(t.TempDir(), "vault")
218		if err := New(dst).Init(); err != nil {
219			t.Fatal(err)
220		}
221		// Delta without the base is refused.
222		if _, err := New(dst).ImportSnapshot(delta); err == nil {
223			t.Fatal("delta imported without a base snapshot")
224		}
225		if _, err := New(dst).ImportSnapshot(full); err != nil {
226			t.Fatal(err)
227		}
228		ires, err := New(dst).ImportSnapshot(delta)
229		if err != nil {
230			t.Fatal(err)
231		}
232		if ires.NewObjects != 2 {
233			t.Fatalf("delta new objects=%d, want 2", ires.NewObjects)
234		}
235		// Add, overwrite, and disappearance are all governed by the target mapping.
236		assertEntriesAfterRestore(t, dst, "target", map[string]string{
237			"keep.txt":   "same",
238			"change.txt": "new",
239			"new.txt":    "brand new",
240		})
241		// gone.txt must not be resurrected by restoring the target.
242		entries, err := New(dst).List()
243		if err != nil {
244			t.Fatal(err)
245		}
246		for _, e := range entries {
247			if e.Name == "gone.txt" {
248				t.Fatal("deleted name reappeared after restore")
249			}
250		}
251	}
