676		goodObj := PackageObject{
677			Digest: d,
678			Size:   int64(len("payload")),
679			Data:   base64.StdEncoding.EncodeToString([]byte("payload")),
680		}
681		goodSnap := Snapshot{Name: "s", Entries: map[string]Entry{
682			"a.txt": {Name: "a.txt", Digest: d, Size: int64(len("payload")), CreatedAt: stamp},
683		}}
684		encode := func(pkg Package) []byte {
685			data, err := json.Marshal(&pkg)
686			if err != nil {
687				t.Fatal(err)
688			}
689			return data
690		}
691		base := func() Package {
692			return Package{
693				Format:   packageFormat,
694				Version:  packageVersion,
695				Snapshot: goodSnap,
696				Objects:  []PackageObject{goodObj},
697			}
698		}
699	
700		cases := map[string]func() Package{
701			"unknown version": func() Package {
702				p := base()
703				p.Version = 99
704				return p
705			},
706			"unknown format": func() Package {
707				p := base()
708				p.Format = "something-else"
709				return p
710			},
711			"bad snapshot name": func() Package {
712				p := base()
713				p.Snapshot = Snapshot{Name: "../escape", Entries: map[string]Entry{
714					"../escape": {Name: "../escape", Digest: d, Size: 7, CreatedAt: stamp},
715				}}
716				return p
717			},
718			"bad entry name": func() Package {
719				p := base()
720				p.Snapshot.Entries["a.txt"] = Entry{Name: "b.txt", Digest: d, Size: 7, CreatedAt: stamp}
721				return p
722			},
723			"bad digest": func() Package {
724				p := base()
725				p.Objects[0].Digest = strings.Repeat("z", 64)
726				return p
727			},
728			"negative size": func() Package {
729				p := base()
730				p.Objects[0].Size = -1
731				return p
732			},
733			"checksum mismatch": func() Package {
734				p := base()
735				p.Objects[0].Digest = digestOf("other")
736				return p
737			},
738			"declared size mismatch": func() Package {
739				p := base()
740				p.Objects[0].Size = 999
741				return p
742			},
743			"snapshot entry size disagrees with healthy content": func() Package {
744				p := base()
745				// The object record stays truthful (7 bytes of payload); only the
746				// snapshot record lies. A second name shares the same digest with
747				// the correct size to prove every name is checked independently.
748				p.Snapshot.Entries["b.txt"] = Entry{Name: "b.txt", Digest: d, Size: 8, CreatedAt: stamp}
749				return p
750			},
751			"bad base64": func() Package {
752				p := base()
753				p.Objects[0].Data = "!!!not base64!!!"
754				return p
755			},
756			"missing content": func() Package {
757				p := base()
758				p.Objects = []PackageObject{}
759				return p
760			},
761			"extra object": func() Package {
762				p := base()
763				p.Objects = append(p.Objects, PackageObject{
764					Digest: digestOf("extra"), Size: 5,
765					Data: base64.StdEncoding.EncodeToString([]byte("extra")),
