868	// TestImportRejectsRecordSizeMismatchWithoutLeavingObject reproduces the
869	// defect: a package carries healthy 7-byte content (its object record honestly
870	// says 7), but the target snapshot records 8 for one of the two names that
871	// share the digest. Import must refuse the whole package and leave neither the
872	// new content object, a snapshot, nor a temporary file behind, and the error
873	// must identify the snapshot, artifact, digest, recorded size, and actual byte
874	// count as a record problem rather than a checksum failure.
875	func TestImportRejectsRecordSizeMismatchWithoutLeavingObject(t *testing.T) {
876		const content = "abcdefg" // exactly 7 bytes
877		d := digestOf(content)
878		pkg := Package{
879			Format:  packageFormat,
880			Version: packageVersion,
881			Snapshot: Snapshot{Name: "s", Entries: map[string]Entry{
882				// a.txt sorts first and is correct; b.txt shares the digest but
883				// lies about the size. Every name must be checked, not just one.
884				"a.txt": entryRec("a.txt", d, 7),
885				"b.txt": entryRec("b.txt", d, 8),
886			}},
887			Objects: []PackageObject{packageObject(content)},
888		}
889		path := writePackage(t, pkg)
890	
891		dst, _ := seedVault(t, map[string]string{"keep.txt": "keep"})
892		before := objectDirNames(t, dst)
893	
894		res, err := New(dst).ImportSnapshot(path)
895		if err == nil {
896			t.Fatal("import accepted a snapshot record whose size disagrees with its content")
897		}
898		msg := err.Error()
899		for _, want := range []string{`snapshot "s"`, "b.txt", d, "8", "7"} {
900			if !strings.Contains(msg, want) {
901				t.Fatalf("error %q does not report %q", msg, want)
902			}
903		}
904		if strings.Contains(msg, "checksum") {
905			t.Fatalf("a record-size mismatch was reported as a checksum failure: %q", msg)
906		}
907		if res != (ImportResult{}) {
908			t.Fatalf("failed import returned a usable result: %+v", res)
909		}
910		if objectExists(dst, d) {
911			t.Fatal("failed import installed the content object anyway")
912		}
913		if infos, _ := New(dst).ListSnapshots(); len(infos) != 0 {
914			t.Fatalf("failed import published a snapshot: %+v", infos)
915		}
916		if after := objectDirNames(t, dst); strings.Join(after, ",") != strings.Join(before, ",") {
917			t.Fatalf("objects directory changed\nbefore: %v\nafter:  %v", before, after)
918		}
919		assertNoTemporaryFiles(t, dst)
920	
921		// The current mapping is untouched.
922		entries, err := New(dst).List()
923		if err != nil {
924			t.Fatal(err)
925		}
926		if len(entries) != 1 || entries[0].Name != "keep.txt" {
927			t.Fatalf("current mapping changed after failed import: %+v", entries)
928		}
929	}
