961	// TestImportDeltaRejectsOmittedRecordSizeMismatch covers incremental packages:
962	// the object the delta omits is healthy in the destination via a matching
963	// base, but the target record keeps its digest while declaring another size.
964	// The package also carries a correct new object; neither it nor the target
965	// snapshot may remain after the refusal.
966	func TestImportDeltaRejectsOmittedRecordSizeMismatchWithoutLeavingNewObject(t *testing.T) {
967		const oldData = "olddata" // 7 bytes, present through the base
968		const newData = "brand new"
969		dOld := digestOf(oldData)
970		dNew := digestOf(newData)
971	
972		dst := filepath.Join(t.TempDir(), "vault")
973		if err := New(dst).Init(); err != nil {
974			t.Fatal(err)
975		}
976		// Establish the matching base snapshot and its object in the destination.
977		basePkg := Package{
978			Format:   packageFormat,
979			Version:  packageVersion,
980			Snapshot: Snapshot{Name: "base", Entries: map[string]Entry{"keep.txt": entryRec("keep.txt", dOld, 7)}},
981			Objects:  []PackageObject{packageObject(oldData)},
982		}
983		if _, err := New(dst).ImportSnapshot(writePackage(t, basePkg)); err != nil {
984			t.Fatal(err)
985		}
986	
987		// Delta: keep.txt keeps the base digest but lies about the size (omitted
988		// object); new.txt is a correct, carried, genuinely new object.
989		delta := Package{
990			Format: packageFormat, Version: packageVersion,
991			Snapshot: Snapshot{Name: "target", Entries: map[string]Entry{
992				"keep.txt": entryRec("keep.txt", dOld, 8),
993				"new.txt":  entryRec("new.txt", dNew, int64(len(newData))),
994			}},
995			Base:    &Snapshot{Name: "base", Entries: map[string]Entry{"keep.txt": entryRec("keep.txt", dOld, 7)}},
996			Objects: []PackageObject{packageObject(newData)},
997		}
998		res, err := New(dst).ImportSnapshot(writePackage(t, delta))
999		if err == nil {
1000			t.Fatal("delta imported a target record that mis-sizes an omitted base object")
1001		}
1002		msg := err.Error()
1003		for _, want := range []string{`snapshot "target"`, "keep.txt", dOld, "8", "7"} {
1004			if !strings.Contains(msg, want) {
1005				t.Fatalf("error %q does not report %q", msg, want)
1006			}
1007		}
1008		if strings.Contains(msg, "checksum") {
1009			t.Fatalf("record-size mismatch reported as checksum failure: %q", msg)
1010		}
1011		if res != (ImportResult{}) {
1012			t.Fatalf("failed delta returned a usable result: %+v", res)
1013		}
1014		if objectExists(dst, dNew) {
1015			t.Fatal("failed delta left the correct new object behind anyway")
1016		}
1017		// Only the base snapshot survives; target is never published.
1018		if infos, _ := New(dst).ListSnapshots(); len(infos) != 1 || infos[0].Name != "base" {
1019			t.Fatalf("snapshots after failed delta: %+v", infos)
1020		}
1021		// The pre-existing base object is byte-for-byte unchanged.
1022		got, err := os.ReadFile(filepath.Join(dst, "objects", dOld))
1023		if err != nil {
1024			t.Fatal(err)
1025		}
1026		if string(got) != oldData {
1027			t.Fatalf("base object altered: %q", got)
1028		}
1029		if names := objectDirNames(t, dst); len(names) != 1 || names[0] != dOld {
1030			t.Fatalf("objects directory after failed delta: %v", names)
1031		}
1032		assertNoTemporaryFiles(t, dst)
1033	}
