405				t.Fatalf("expected error naming object %s, got %v", entry.Digest, err)
406			}
407			if strings.Contains(err.Error(), "output") {
408				t.Fatalf("object failure misreported as an output error: %v", err)
409			}
410			if _, err := os.Stat(out); !errors.Is(err, os.ErrNotExist) {
411				t.Fatal("failed export created an output")
412			}
413			if err := os.WriteFile(obj, good, 0o644); err != nil {
414				t.Fatal(err)
415			}
416		})
417		t.Run("checksum mismatch preserves the existing package", func(t *testing.T) {
418			obj := filepath.Join(root, "objects", entry.Digest)
419			good, err := os.ReadFile(obj)
420			if err != nil {
421				t.Fatal(err)
422			}
423			out := filepath.Join(t.TempDir(), "snap.pkg")
424			if _, err := store.ExportSnapshot("snap", "", out); err != nil {
425				t.Fatal(err)
426			}
427			sentinel, err := os.ReadFile(out)
428			if err != nil {
429				t.Fatal(err)
430			}
431			if err := os.WriteFile(obj, []byte("X"), 0o644); err != nil {
432				t.Fatal(err)
433			}
434			if _, err := store.ExportSnapshot("snap", "", out); err == nil {
435				t.Fatal("export of a corrupt object succeeded")
436			}
437			got, err := os.ReadFile(out)
438			if err != nil {
439				t.Fatal(err)
440			}
441			if string(got) != string(sentinel) {
442				t.Fatal("failed export replaced the existing package")
443			}
444			if err := os.WriteFile(obj, good, 0o644); err != nil {
445				t.Fatal(err)
446			}
447		})
448	}
