450	func TestExportDoesNotModifyRepository(t *testing.T) {
451		root, store, entry := exportVault(t, "payload")
452		paths := []string{
453			filepath.Join(root, "index.json"),
454			filepath.Join(root, ".lock"),
455			filepath.Join(root, "snapshots", "snap.json"),
456			filepath.Join(root, "objects", entry.Digest),
457		}
458		before := map[string][]byte{}
459		for _, p := range paths {
460			data, err := os.ReadFile(p)
461			if err != nil {
462				t.Fatal(err)
463			}
464			before[p] = data
465		}
466		out := filepath.Join(t.TempDir(), "snap.pkg")
467		if _, err := store.ExportSnapshot("snap", "", out); err != nil {
468			t.Fatal(err)
469		}
470		for _, p := range paths {
471			after, err := os.ReadFile(p)
472			if err != nil {
473				t.Fatal(err)
474			}
475			if string(after) != string(before[p]) {
476				t.Fatalf("repository file %s changed across export", p)
477			}
478		}
479	}
