481	func TestExportRetryAfterLeftoverTemp(t *testing.T) {
482		_, store, _ := exportVault(t, "payload")
483		dir := t.TempDir()
484		// Simulate a temporary file left by an export process that died.
485		leftover := filepath.Join(dir, ".package-deadbeef")
