502	func TestExportEmptySnapshotAndObjectlessDelta(t *testing.T) {
503		root := filepath.Join(t.TempDir(), "vault")
504		if err := New(root).Init(); err != nil {
505			t.Fatal(err)
506		}
507		if _, err := New(root).CreateSnapshot("empty"); err != nil {
508			t.Fatal(err)
509		}
510		out := filepath.Join(t.TempDir(), "empty.pkg")
511		res, err := New(root).ExportSnapshot("empty", "", out)
512		if err != nil {
