514		}
515		if res.Entries != 0 || res.Objects != 0 {
516			t.Fatalf("empty export result=%+v", res)
517		}
518		// A delta carrying no new objects must still produce a package.
519		out2 := filepath.Join(t.TempDir(), "delta.pkg")
520		res2, err := New(root).ExportSnapshot("empty", "empty", out2)
521		if err != nil {
522			t.Fatal(err)
523		}
524		if res2.Objects != 0 {
525			t.Fatalf("objectless delta carried %d objects", res2.Objects)
526		}
