529	// TestExportCommitDetectsParentSwap performs the parent-replacement race the
530	// pin-and-revalidate commit is designed to stop: while the package is being
531	// staged, the output's parent directory is replaced by a symlink to the
532	// repository and the output name is made to collide with the index. The
533	// export must refuse and leave every repository file untouched.
534	func TestExportCommitDetectsParentSwap(t *testing.T) {
535		if testing.Short() {
536			t.Skip("skipping timing-sensitive test in short mode")
537		}
538		root, store := seedVault(t, map[string]string{"big.txt": strings.Repeat("ab", 5<<20)})
539		if _, err := store.CreateSnapshot("snap"); err != nil {
540			t.Fatal(err)
541		}
542		indexBefore, err := os.ReadFile(filepath.Join(root, "index.json"))
543		if err != nil {
544			t.Fatal(err)
545		}
546	
547		outside := t.TempDir()
548		outdir := filepath.Join(outside, "deliver")
549		if err := os.Mkdir(outdir, 0o755); err != nil {
550			t.Fatal(err)
551		}
552		// "index.json" inside a directory symlinked to the repository would
553		// overwrite the real index if the commit followed the swapped path.
554		out := filepath.Join(outdir, "index.json")
555	
556		var wg sync.WaitGroup
557		wg.Add(1)
558		var exportErr error
559		go func() {
560			defer wg.Done()
561			_, exportErr = store.ExportSnapshot("snap", "", out)
562		}()
563	
564		// Swap as soon as the package temp file appears in the pinned directory.
565		deadline := time.Now().Add(10 * time.Second)
566		swapped := false
567		for time.Now().Before(deadline) {
568			entries, err := os.ReadDir(outdir)
569			if err != nil {
570				t.Fatal(err)
571			}
572			for _, e := range entries {
573				if strings.HasPrefix(e.Name(), ".package-") {
574					if err := os.Rename(outdir, outdir+".real"); err != nil {
575						t.Fatal(err)
576					}
577					if err := os.Symlink(root, outdir); err != nil {
578						t.Fatal(err)
579					}
580					swapped = true
581					break
582				}
583			}
584			if swapped {
585				break
586			}
587			time.Sleep(time.Millisecond)
588		}
589		if !swapped {
590			t.Fatal("never observed the staged package temp file")
591		}
592		wg.Wait()
593	
594		if exportErr == nil || !strings.Contains(exportErr.Error(), "unsafe") {
595			t.Fatalf("expected unsafe-output error after parent swap, got %v", exportErr)
596		}
597		indexAfter, err := os.ReadFile(filepath.Join(root, "index.json"))
598		if err != nil {
599			t.Fatal(err)
600		}
601		if string(indexAfter) != string(indexBefore) {
602			t.Fatal("the repository index was overwritten through the swapped parent")
603		}
604		if _, err := os.Stat(filepath.Join(root, "index.json.tmp")); err == nil {
605			t.Fatal("stray temp file landed in the repository")
606		}
607		// The package must not have appeared inside the repository under any name.
608		if entries, err := os.ReadDir(root); err != nil {
609			t.Fatal(err)
610		} else {
611			for _, e := range entries {
612				if strings.HasPrefix(e.Name(), ".package-") {
613					t.Fatal("package temp file committed into the repository")
614				}
615			}
616		}
617	}
618	
619	// --- command-line parity -----------------------------------------------------
620	
621	var (
622		exportBinaryOnce sync.Once
623		exportBinaryPath string
624		exportBinaryErr  error
625	)
626	
627	func exportBinary(t *testing.T) string {
628		t.Helper()
629		exportBinaryOnce.Do(func() {
630			dir, err := os.MkdirTemp("", "artifact-vault-build-")
631			if err != nil {
632				exportBinaryErr = err
633				return
634			}
635			bin := filepath.Join(dir, "artifact-vault")
636			exportBinaryErr = exec.Command("go", "build", "-o", bin, "../../cmd/artifact-vault").Run()
637			exportBinaryPath = bin
638		})
639		if exportBinaryErr != nil {
640			t.Fatalf("build CLI: %v", exportBinaryErr)
641		}
642		return exportBinaryPath
643	}
644	
645	func TestExportCLIParity(t *testing.T) {
646		root, _, _ := exportVault(t, "payload")
647		if _, err := New(root).CreateSnapshot("base"); err != nil {
648			t.Fatal(err)
649		}
650		bin := exportBinary(t)
651	
652		t.Run("unsafe output is refused on the command line", func(t *testing.T) {
653			cmd := exec.Command(bin, "snapshot", "export", "--root", root,
654				"--name", "snap", "--output", filepath.Join(root, "index.json"))
655			var stderr strings.Builder
656			cmd.Stderr = &stderr
657			if err := cmd.Run(); err == nil {
658				t.Fatal("CLI export over the index succeeded")
659			}
660			if !strings.Contains(stderr.String(), "inside the repository") {
661				t.Fatalf("stderr=%q", stderr.String())
662			}
663		})
664		t.Run("unsafe delta output is refused on the command line", func(t *testing.T) {
665			cmd := exec.Command(bin, "snapshot", "export", "--root", root,
666				"--name", "snap", "--base", "base", "--output", filepath.Join(root, "objects", digestOf("payload")))
667			var stderr strings.Builder
668			cmd.Stderr = &stderr
669			if err := cmd.Run(); err == nil {
670				t.Fatal("CLI delta export over an object succeeded")
671			}
672			if !strings.Contains(stderr.String(), "inside the repository") {
673				t.Fatalf("stderr=%q", stderr.String())
674			}
675		})
676		t.Run("successful CLI export keeps the summary", func(t *testing.T) {
677			out := filepath.Join(t.TempDir(), "snap.pkg")
678			cmd := exec.Command(bin, "snapshot", "export", "--root", root,
679				"--name", "snap", "--output", out)
680			var stdout, stderr strings.Builder
681			cmd.Stdout = &stdout
682			cmd.Stderr = &stderr
683			if err := cmd.Run(); err != nil {
684				t.Fatalf("CLI export failed: %v %q", err, stderr.String())
685			}
686			if want := fmt.Sprintf("exported snapshot snap with %d entries, %d objects\n", 1, 1); stdout.String() != want {
687				t.Fatalf("stdout=%q, want %q", stdout.String(), want)
688			}
689		})
690	}
